D="10. Кызылординская область/договора/"
C=D+"Договор поручения рус.doc"
X=D+"Приложение 6-9.xlsx"
A10=D+"приложение 10.docx"
def it(part,topic,summary,ref,quote=""):
    return {"part":part,"topic":topic,"summary":summary,"ref":ref,"quote":quote}
items41=[]
def sheet(part,ru,kk,xr,n_cols,title,index,period,pcode,cols,foot,extra):
    P=part
    r=f"{X}, лист «{ru}»"
    items41.append(it(P,"Назначение приложения",f"Форма ежемесячного отчёта: «{title}»; индекс формы административных данных: {index}. Договор упоминает её в составе отчётов п. 4.1 пп. 14) (Приложения №6, №7, №8, №9).",f"{r}, ячейки A{pcode[0]}:A{pcode[1]}; {C}, п. 4.1 пп. 14)",f"{title} | {index} | {period}"))
    items41.append(it(P,"Периодичность",f"{period}; отчётный период: «месяц 20__ года» (пустое поле). По договору отчёты предоставляются ежемесячно до 5 числа месяца, следующего за отчётным. В самой форме срок не указан.",f"{r}, ячейка A{pcode[2]}; {C}, п. 4.1 пп. 14)","ежемесячно, в срок до 5 числа месяца, следующего за отчетным"))
    items41.append(it(P,"Кому адресовано",f"В форме адресат не указан. По п. 4.1 пп. 14) договора отчёт предоставляется Поверенным агентом (исполнитель) в местный исполнительный орган по вопросам сельского хозяйства. Шапка формы: «Приложение к Договору поручения № ___ от «__»____ 20__ года».",f"{r}, ячейка {xr}; {C}, п. 4.1 пп. 14)","предоставляет в местный исполнительный орган по вопросам сельского хозяйства отчет"))
    items41.append(it(P,"Содержание (столбцы формы)",f"Нумерация столбцов в строке {cols[0]}: {n_cols}. Столбцы: {cols[1]}",f"{r}, ячейки {cols[2]}",cols[3]))
    items41.append(it(P,"Числовые значения",extra[0],f"{r}, {extra[1]}",extra[2]))
    items41.append(it(P,"Подписи и реквизиты",foot[0],f"{r}, ячейки {foot[1]}",foot[2]))

